const uint8_t *tft_chinese_font_find(uint16_t codepoint) {
    for (size_t i = 0U; i < sizeof(g_chinese_glyphs) /
                                  sizeof(g_chinese_glyphs[0]); i++) {
        if (g_chinese_glyphs[i].codepoint == codepoint) {
            return g_chinese_glyphs[i].rows;
        }
    }
    return NULL;
}
